export { descriptionId, legendId, view } from "../fieldset";
export type { FieldsetAttributes, ViewConfig } from "../fieldset";

export {
  fieldsetClassName as baseUiFieldsetRootClassName,
  legendClassName as baseUiFieldsetLegendClassName,
  descriptionClassName as baseUiFieldsetDescriptionClassName,
} from "./view";

import { describe, expect, test } from "vitest";

import * as Fieldset from "./index";

describe("Base UI Fieldset registry view", () => {
  test("reuses the Foldkit Fieldset functional contract", () => {
    expect(Fieldset.view).toBeTypeOf("function");
    expect(Fieldset.legendId).toBeTypeOf("function");
    expect(Fieldset.baseUiFieldsetRootClassName).toContain("rounded-lg");
  });
});
